.map-view-sheet__toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.78rem;
  cursor: pointer;
}

.map-view-sheet__toggle input {
  accent-color: #2563EB;
}

.map-view-sheet__toggle input:disabled {
  cursor: not-allowed;
}

