  font-weight: 650;
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
  border: 1px solid #CBD5E1;
  background: #F1F5F9;
  color: #475569;
  cursor: pointer;
}

.map-view-sheet__close:hover {
  background: #EFF6FF;
  border-color: #2563EB;
}

.map-view-sheet__panel {
  padding: 0.4rem 0.55rem 0.55rem;
  gap: 0.35rem;
  max-height: calc(100vh - 1rem);
  max-height: calc(100dvh - 1rem);
}

.map-view-sheet__handle {
  display: none;
}

@media (max-height: 560px) {
  .map-view-sheet__panel {
    width: min(25rem, calc(100vw - 1rem));
  }
}

